#include <stdio.h>

void swap_copy(int a, int b) {
    int t = a; a = b; b = t;
}

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int main(void) {
    int x = 4, y = 9;

    swap_copy(x, y);
    printf("after swap_copy: x=%d y=%d\n", x, y);

    swap(&x, &y);
    printf("after swap: x=%d y=%d\n", x, y);
    return 0;
}

#include <stdio.h>
#include <string.h>

typedef struct {
    char name[20];
    int roll;
    float gpa;
} Student;

void print_student(const Student *sp) {
    printf("%s (roll %d) GPA %.1f\n", sp->name, sp->roll, sp->gpa);
}

int main(void) {
    Student s = {"Ayesha", 12, 3.6f};
    print_student(&s);

    Student copy = s;          /* copies every member */
    strcpy(copy.name, "Bilal");
    copy.roll = 13;

    print_student(&s);
    print_student(&copy);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n = 5;
    int *nums = malloc(n * sizeof(int));
    if (nums == NULL) {
        printf("Out of memory\n");
        return 1;
    }

    int sum = 0;
    for (int i = 0; i < n; i++) {
        nums[i] = (i + 1) * 10;
        sum += nums[i];
    }
    printf("Sum = %d\n", sum);

    free(nums);       /* give the memory back */
    nums = NULL;
    return 0;
}

#include <stdio.h>

int main(void) {
