    if (f == NULL) {
        printf("Cannot read file\n");
        return 1;
    }
    char line[50];
    while (fgets(line, sizeof(line), f) != NULL) {
        printf("Read: %s", line);
    }
    fclose(f);

    remove("scores.txt");   /* clean up the demo file */
    return 0;
}
